B-129.command:
set -euo pipefail; test "${OWNER_APPROVED_PROBE:?set OWNER_APPROVED_PROBE=1 for the approved diagnostic window}" = 1; export D03_SAMPLE_COUNT=10 SERVER_TIMING_WDB_DETAIL=on; : > artifacts/d03/B129-production-residual.json; grep -Fq 'diagnostic' docs/handoff/2026-09-05-b103-b129-attribution-owner-packet.md; for ordinal in $(seq 1 10); do headers="$(mktemp)"; curl --silent --show-error --output /dev/null --dump-header "$headers" --write-out "sample=$ordinal status=%{http_code} wall_ms=%{time_total}\n" -H "Authorization: Bearer ${CORELINK_DOGFOOD_PAT:?}" -H 'X-Server-Timing-Wdb-Detail: on' "$CORELINK_PROD_BASE/v1/customer/cas/probe?sample=$ordinal" | tee -a artifacts/d03/B129-production-residual.json; tr -d '\r' < "$headers" | grep -i '^server-timing:' | tee -a artifacts/d03/B129-production-residual.json; rm -f "$headers"; done; git log -1 --format='deployed commit %H' | tee -a artifacts/d03/B129-production-residual.json; python3 -c 'import re,sys; rows=[]; required={"qtier","qdo","qbatch","qresid","qcontrol","ohop","wdb","origin","total"};
for line in open(sys.argv[1], encoding="utf-8"):
 values={k:float(v) for k,v in re.findall(r"([a-z][a-z0-9_]*);dur=([0-9.]+)", line.lower())};
 if not required.issubset(values): continue
 residual=max(0.0, values["total"]-(values["wdb"]+values["origin"])); rows.append(100.0*residual/values["total"] if values["total"] else 100.0)
if not rows or max(rows) >= 10.0: raise SystemExit(1)
print(f"residual_max_pct=<10%:{max(rows):.2f}")' artifacts/d03/B129-production-residual.json | tee -a artifacts/d03/B129-production-residual.json; grep -Eiq 'server-timing:.*qtier.*qdo.*qbatch.*qresid.*qcontrol.*ohop.*wdb.*origin|residual_max_pct=<10%' artifacts/d03/B129-production-residual.json
